def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def term_has(value,name):
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def is_maud_statement(term):
    names=['company_knowledge_definition','operative_knowledge_inquiry_duty','knowledge_inquiry_exclusion','interim_covenant']
    for name in names:
        if term_has(term,name):
            return True
    return False

def apply(inputs,premises):
    source_output=inputs.get('source_output',{})
    out=[]
    unresolved=[]
    has_maud=False
    if isinstance(source_output,dict):
        for row in source_output.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(out,row.get('term'),row.get('support_ids',[]))
                if is_maud_statement(row.get('term')):
                    has_maud=True
        for value in source_output.get('unresolved',[]):
            if has_maud and value=='Complete-source disposal review is pending; absence is not inferred from deterministic non-matching.':
                continue
            if value not in unresolved:
                unresolved.append(value)
    complete=False
    if len(unresolved)==0:
        if has_maud:
            complete=True
        elif isinstance(source_output,dict) and source_output.get('complete') is True:
            complete=True
    return {'statements':out,'complete':complete,'unresolved':unresolved}

