def subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def has_tag(value,name):
    for item in subterms(value):
        if item[0]==name:
            return True
    return False

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def root_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        by_id[node.get('id')]=node
    out=[]
    for root in roots:
        node=by_id.get(root)
        if isinstance(node,dict) and isinstance(node.get('term'),list):
            out.append((root,node.get('term')))
    return out

def apply(inputs,premises):
    task=inputs.get('task_id')
    entries=root_entries(premises)
    if task=='Knowledge Definition-Answer':
        qualified=[]
        actual=[]
        relevant=[]
        for root,term in entries:
            if has_tag(term,'company_knowledge_definition'):
                relevant.append(root)
                if has_tag(term,'inquiry_qualified_knowledge_standard') or has_tag(term,'deemed_knowledge_standard'):
                    qualified.append(root)
                elif has_tag(term,'unqualified_actual_knowledge_standard'):
                    actual.append(root)
            if has_tag(term,'operative_knowledge_inquiry_duty'):
                qualified.append(root)
                relevant.append(root)
        if qualified:
            return {'handled':True,'answer':'Constructive knowledge','used_nodes':unique(qualified+relevant)}
        if actual:
            return {'handled':True,'answer':'Actual knowledge','used_nodes':unique(actual)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='Ordinary Course Covenant includes carve-out for Pandemic responses-Answer (Y/N)':
        wanted='ordinary_course_effect'
    elif task=='Negative Interim Covenant includes carveout for pandemic responses-Answer (Y/N)':
        wanted='negative_interim_effect'
    else:
        return {'handled':False,'answer':None,'used_nodes':[]}
    yes=[]
    no=[]
    for root,term in entries:
        if not has_tag(term,'interim_covenant') or not has_tag(term,wanted):
            continue
        if has_tag(term,'covenant_exception_inventory_with_pandemic') and has_tag(term,'pandemic_response_exception'):
            yes.append(root)
        elif has_tag(term,'covenant_exception_inventory_without_pandemic'):
            no.append(root)
    if yes:
        return {'handled':True,'answer':'Yes','used_nodes':unique(yes)}
    if no:
        return {'handled':True,'answer':'No','used_nodes':unique(no)}
    return {'handled':False,'answer':None,'used_nodes':[]}

