def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def add_statement(out,term,support_ids):
    support=unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def text_value(value):
    if isinstance(value,str):
        return value
    return str(value)

def has_any(text,phrases):
    for phrase in phrases:
        if phrase in text:
            return True
    return False

def all_ids(spans):
    out=[]
    for span in spans:
        uid=span.get('id')
        if uid not in out:
            out.append(uid)
    return out

def support_for(spans,phrases):
    out=[]
    for span in spans:
        raw=text_value(span.get('text',''))
        low=raw.casefold()
        if has_any(low,phrases):
            uid=span.get('id')
            if uid not in out:
                out.append(uid)
    if out:
        return out
    return all_ids(spans)

def earliest_after(text,markers,start):
    best=-1
    chosen=''
    for marker in markers:
        pos=text.find(marker,start)
        if pos>=0 and (best<0 or pos<best):
            best=pos
            chosen=marker
    return best,chosen

def definition_clause(raw):
    low=raw.casefold()
    pos=low.find('knowledge')
    if pos<0:
        return ''
    end=raw.find('.',pos)
    if end<0:
        return raw[pos:].strip()
    return raw[pos:end+1].strip()

def extract_holders(raw,clause):
    low=raw.casefold()
    base=raw.find(clause) if clause else 0
    if base<0:
        base=0
    local=clause.casefold() if clause else low
    markers=['actual knowledge of ','of each of ','of the individuals ','of those individuals ','individuals named on ','individuals listed in ']
    pos,marker=earliest_after(local,markers,0)
    if pos<0:
        means=local.find('means')
        if means>=0:
            start=means+len('means')
        else:
            start=0
    else:
        start=pos
        if marker=='actual knowledge of ':
            start=pos+len('actual knowledge of ')
    ends=[]
    for stop in [' in each case',', in each case',' after reasonable inquiry',';','.', ' (page']:
        value=local.find(stop,start)
        if value>=0:
            ends.append(value)
    end=min(ends) if ends else len(clause)
    value=clause[start:end].strip(' ,;:')
    if value:
        return value
    return clause.strip()

def extract_scope(clause):
    low=clause.casefold()
    phrase='with respect to any matter in question'
    pos=low.find(phrase)
    if pos>=0:
        return clause[pos:pos+len(phrase)]
    means=low.find('means')
    if means>0:
        value=clause[:means].strip(' ,;:')
        if value:
            return value
    return clause.strip()

def sentence_at(raw,pos):
    if pos<0:
        return ''
    start=raw.rfind('.',0,pos)
    if start<0:
        start=0
    else:
        start+=1
    end=raw.find('.',pos)
    if end<0:
        end=len(raw)
    else:
        end+=1
    return raw[start:end].strip()

def exclusion_parts(raw):
    low=raw.casefold()
    start=low.find('with respect to')
    if start<0:
        start=low.find('intellectual property')
    if start<0:
        return '',''
    block=raw[start:].strip()
    block_low=block.casefold()
    split=-1
    for marker in [' and no knowledge',' and if not conducted','; no knowledge',', no knowledge']:
        pos=block_low.find(marker)
        if pos>=0 and (split<0 or pos<split):
            split=pos
    if split<0:
        return block,block
    return block[:split].strip(' ,;'),block[split:].strip(' ,;')

def find_actor(raw,start):
    low=raw.casefold()
    markers=['each of the company parties will','each company party will','the company parties will not','the company parties will','the company shall not','the company will not','the company shall','the company will','company parties will not','company parties will']
    return earliest_after(low,markers,start)

def actor_text(raw,pos,marker):
    if pos<0:
        return ''
    low=raw.casefold()
    shall=low.find(' shall',pos)
    will=low.find(' will',pos)
    ends=[]
    if shall>=0:
        ends.append(shall)
    if will>=0:
        ends.append(will)
    end=min(ends) if ends else pos+len(marker)
    return raw[pos:end].strip(' ,;:')

def pandemic_reference(raw):
    low=raw.casefold()
    markers=['covid-19 measures','covid-19 pandemic','covid-19','covid 19','coronavirus','pandemic']
    pos,marker=earliest_after(low,markers,0)
    if pos<0:
        return ''
    return raw[pos:pos+len(marker)]

def seed_output(inputs):
    seed=inputs.get('source_output',{})
    statements=[]
    unresolved=[]
    complete=True
    if isinstance(seed,dict):
        for row in seed.get('statements',[]):
            if isinstance(row,dict) and isinstance(row.get('term'),list):
                add_statement(statements,row.get('term'),row.get('support_ids',[]))
        for value in seed.get('unresolved',[]):
            if value not in unresolved:
                unresolved.append(value)
        if seed.get('complete') is False:
            complete=False
    return statements,unresolved,complete

def apply(inputs,premises):
    spans=inputs.get('source_spans',[])
    out,unresolved,seed_complete=seed_output(inputs)
    if not isinstance(spans,list) or not spans:
        if 'No current source spans were supplied to the MAUD source parser.' not in unresolved:
            unresolved.append('No current source spans were supplied to the MAUD source parser.')
        return {'statements':out,'complete':False,'unresolved':unresolved}
    raw=text_value(inputs.get('source_text',''))
    low=raw.casefold()
    ids=all_ids(spans)
    recognized=False
    if 'knowledge' in low and 'means' in low:
        recognized=True
        clause=definition_clause(raw)
        clause_low=clause.casefold()
        holder_text=extract_holders(raw,clause)
        holders=['source_designated_knowledge_holders',holder_text]
        inquiry=has_any(clause_low,['after reasonable inquiry','after due inquiry','after diligent inquiry','after appropriate inquiry','reasonable investigation','after inquiry'])
        deemed=has_any(clause_low,['should have known','would have known','constructive knowledge'])
        actual='actual knowledge' in clause_low
        if inquiry:
            standard=['inquiry_qualified_knowledge_standard',clause]
        elif deemed:
            standard=['deemed_knowledge_standard',clause]
        elif actual:
            standard=['unqualified_actual_knowledge_standard',clause]
        else:
            standard=None
        if standard is None:
            message='The current knowledge definition was found, but its knowledge standard was not safely classified.'
            if message not in unresolved:
                unresolved.append(message)
        else:
            add_statement(out,['company_knowledge_definition',holders,standard,clause],support_for(spans,['knowledge','actual knowledge']))
            if inquiry:
                inquiry_pos=clause_low.find('inquir')
                inquiry_text=sentence_at(clause,inquiry_pos)
                add_statement(out,['operative_knowledge_inquiry_duty',holders,extract_scope(clause),inquiry_text],support_for(spans,['inquir']))
        if has_any(low,['intellectual property','patent','freedom-to-operate','freedom to operate']) and has_any(low,['does not require','no knowledge','will be imputed','will not be imputed']):
            procedure,effect=exclusion_parts(raw)
            if procedure and effect:
                add_statement(out,['knowledge_inquiry_exclusion',holders,procedure,effect],support_for(spans,['intellectual property','patent','freedom-to-operate','imputed']))
    covenant_signal=has_any(low,['ordinary course','forbearance covenants','the company shall not','the company will not','company parties will not'])
    if covenant_signal:
        except_pos=low.find('except')
        actor_start=except_pos if except_pos>=0 else 0
        actor_pos,actor_marker=find_actor(raw,actor_start)
        if actor_pos<0:
            message='A possible interim covenant was found, but its operative actor and effect were not safely delimited.'
            if message not in unresolved:
                unresolved.append(message)
        else:
            effect_text=raw[actor_pos:].strip()
            effect_low=effect_text.casefold()
            negative=has_any(actor_marker,['shall not','will not']) or has_any(effect_low[:180],['shall not','will not','nor shall','will not permit']) or 'forbearance covenants' in low
            ordinary='ordinary course' in effect_low or ('ordinary course' in low and not negative)
            if negative or ordinary:
                recognized=True
                actor=['source_designated_covenant_actor',actor_text(raw,actor_pos,actor_marker)]
                if negative:
                    effect=['negative_interim_effect',effect_text]
                else:
                    effect=['ordinary_course_effect',effect_text]
                if except_pos>=0 and except_pos<actor_pos:
                    exception_text=raw[except_pos:actor_pos].strip(' ,;:')
                else:
                    exception_text=''
                reference=pandemic_reference(exception_text)
                if reference:
                    exception=['pandemic_response_exception',exception_text,reference]
                    inventory=['covenant_exception_inventory_with_pandemic',exception_text,exception]
                else:
                    inventory=['covenant_exception_inventory_without_pandemic',exception_text]
                add_statement(out,['interim_covenant',actor,effect,inventory,effect_text],ids)
    complete=seed_complete and len(unresolved)==0
    if recognized and len(unresolved)==0:
        complete=True
    return {'statements':out,'complete':complete,'unresolved':unresolved}
